perl -e '
my $root = "/bench/repo";
my @entities = qw(User Memo Attachment Reaction Inbox MemoRelation MemoShare IdentityProvider UserIdentity UserSetting InstanceSetting Store);

my @files = split /\n/, `find $root -name "*.go" ! -name "*_test.go" ! -path "*/proto/gen/*" ! -path "*/web/*"`;

sub pkg_of {
  my ($f)=@_; $f=~s/^\Q$root\E\/?//; $f=~s/\/[^\/]+$//; $f=~s/\\/\//g; $f;
}

my %pkg_refs; # entity -> {pkg => 1}
for my $f (@files) {
  my $pkg = pkg_of($f);
  next if $pkg =~ /^store(\/|$)/;  # outside store layer
  open my $fh, "<", $f or next;
  my $content = do { local $/; <$fh> };
  close $fh;
  for my $e (@entities) {
    if ($content =~ /\bstore\.\Q$e\E\b/) {
      $pkg_refs{$e}{$pkg} = 1;
    }
  }
}

my @sorted = sort { scalar(keys %{$pkg_refs{$b}}) <=> scalar(keys %{$pkg_refs{$a}}) || $a cmp $b } @entities;
for my $e (@sorted) {
  my $n = scalar keys %{$pkg_refs{$e}};
  print "$n\t$e\n";
  for my $p (sort keys %{$pkg_refs{$e}}) {
    print "  $p\n";
  }
  print "\n";
}
'

perl -e '
my $root = "/bench/repo";
# core persistent entities only
my @entities = qw(User Memo Attachment Reaction Inbox MemoRelation MemoShare IdentityProvider UserIdentity UserSetting InstanceSetting);

my @files = split /\n/, `find $root -name "*.go" ! -name "*_test.go" ! -path "*/proto/gen/*" ! -path "*/web/*" ! -path "*/store/test/*"`;

sub pkg_of { my ($f)=@_; $f=~s/^\Q$root\E\/?//; $f=~s/\/[^\/]+$//; $f=~s/\\/\//g; $f; }

my %pkg_refs;
for my $f (@files) {
  my $pkg = pkg_of($f);
  next if $pkg =~ /^store(\/|$)/;
  next if $pkg =~ /\/test$/;  # exclude test helper packages
  open my $fh, "<", $f or next;
  my $content = do { local $/; <$fh> };
  close $fh;
  for my $e (@entities) {
    next unless $content =~ /\bstore\.\Q$e\E\b/;
    $pkg_refs{$e}{$pkg} = 1;
  }
}

my @sorted = sort { scalar(keys %{$pkg_refs{$b}}) <=> scalar(keys %{$pkg_refs{$a}}) || $a cmp $b } @entities;
for my $e (@sorted) {
  my @pkgs = sort keys %{$pkg_refs{$e}};
  print scalar(@pkgs), "\t$e\t", join(", ", @pkgs), "\n";
}
'

